// План specs/seo.md, 2.1 (кейс SEO-03). Гость, только GET-запросы к лендингу https://techory.ai. @prod-safe
import { test, expect } from '@playwright/test';

test.describe('SEO — robots.txt (#8d3f16b1)', () => {
  test('robots.txt returns 200 text/plain with User-agent, Allow and a Sitemap line #8d3f16b1 @desktop @prod-safe', async ({ request }) => {
    const res = await request.get('https://techory.ai/robots.txt');
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type']).toContain('text/plain');

    const lines = (await res.text()).split(/\r?\n/).map((l) => l.trim());
    expect(lines).toContain('User-agent: *');
    expect(lines).toContain('Allow: /');
    expect(lines).toContain('Sitemap: https://techory.ai/sitemap.xml');
    expect(lines.join('\n')).not.toContain('<html'); // не SPA-заглушка

    // Ссылка Sitemap ведёт на настоящий XML
    const sitemap = await request.get('https://techory.ai/sitemap.xml');
    expect(sitemap.status()).toBe(200);
    expect(sitemap.headers()['content-type']).toContain('application/xml');
  });
});
